<script setup lang="ts">
import { ArrowLeft, ArrowRight, Sparkles } from '@lucide/vue'
import { nextTick, onMounted, onBeforeUnmount, ref } from 'vue'
import { useApi } from '../../../composables/useApi';
const fallback='/images/trove-landscape.svg'
const fallbackImage=(event:Event)=>{const image=event.target as HTMLImageElement;if(image.src!==fallback)image.src=fallback}
const carousel=ref<HTMLElement|null>(null); const activeIndex=ref(0); const pageCount=ref(1); const visibleCount=ref(3)
const recalcCarousel=()=>{ if(!carousel.value) return; const cards=Array.from(carousel.value.children) as HTMLElement[]; if(!cards.length){pageCount.value=1;return}; const first=cards[0]; const gap=parseFloat(getComputedStyle(carousel.value).columnGap || getComputedStyle(carousel.value).gap || '18') || 18; visibleCount.value=Math.max(1,Math.round((carousel.value.clientWidth + gap)/(first.getBoundingClientRect().width + gap))); pageCount.value=Math.max(1,Math.ceil(cards.length/visibleCount.value)); activeIndex.value=Math.min(activeIndex.value,pageCount.value-1) }
const goTo=(page:number)=>{ if(!carousel.value)return; recalcCarousel(); const cards=carousel.value.children; const index=Math.min(page*visibleCount.value,cards.length-1); const target=cards[index] as HTMLElement|undefined; if(!target)return; carousel.value.scrollTo({left:Math.max(0,target.offsetLeft-2),behavior:'smooth'}); activeIndex.value=page }
const moveCarousel=(delta:number)=>goTo(Math.min(Math.max(activeIndex.value+delta,0),pageCount.value-1))
const updateActive=()=>{if(!carousel.value)return; recalcCarousel(); const left=carousel.value.scrollLeft; const cards=Array.from(carousel.value.children) as HTMLElement[]; let nearestPage=0; let distance=Infinity; cards.forEach((card,index)=>{const d=Math.abs(card.offsetLeft-left);if(d<distance){distance=d;nearestPage=Math.floor(index/visibleCount.value)}}); activeIndex.value=Math.min(nearestPage,pageCount.value-1)}
const onResize=()=>{recalcCarousel();updateActive()}
onMounted(()=>{window.addEventListener('resize',onResize);nextTick(()=>{ recalcCarousel(); updateActive() })})
onBeforeUnmount(()=>window.removeEventListener('resize',onResize))
const articles=ref([
 {slug:'choose-hotel',tag:'Советы',time:'6 мин',title:'Как выбрать отель и не пожалеть',text:'Что смотреть кроме звёзд и красивой фотографии.',image:'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=85'},
 {slug:'warm-sea-autumn',tag:'Направления',time:'8 мин',title:'Турция: море, которое не надоедает',text:'Когда ехать, какой регион выбрать и кому что подойдёт.',image:'https://images.unsplash.com/photo-1534777367038-9404f45b8693?auto=format&fit=crop&w=900&q=85'},
 {slug:'dubai-without-rush',tag:'Города',time:'5 мин',title:'Дубай без гонки за достопримечательностями',text:'Как совместить море, город и пару красивых вечеров.',image:'https://images.unsplash.com/photo-1642577784769-527a61364162?auto=format&fit=crop&w=900&q=85'},
 {slug:'hotel-by-the-sea',tag:'Советы',time:'4 мин',title:'Как понять, что отель действительно у моря',text:'Разбираемся с первой линией, пляжем и тем, что скрывается за красивым видом.',image:'https://images.unsplash.com/photo-1564501049412-61c2a3083791?auto=format&fit=crop&w=900&q=85'}
])

const api=useApi()
try {
  const remote=await api<{items:any[]}>('/api/guides')
  const existing=new Set(articles.value.map(item=>item.slug))
  for (const item of remote.items) {
    if (existing.has(item.slug)) continue
    articles.value.push({slug:item.slug,tag:'Trove Гид',time:'6 мин',title:item.title,text:item.excerpt||'',image:item.cover_url||fallback})
  }
} catch {}
</script>
